insert into general_quiz_questions (difficulty, question_text, options, correct_answer, explanation)
values
  ('easy', 'What does "AI" stand for?', '["Automated Internet", "Artificial Intelligence", "Advanced Integration", "Application Interface"]'::jsonb, 'Artificial Intelligence', 'AI means "Artificial Intelligence": machines built to think or act smart, like a computer brain.'),
  ('easy', 'What is a "password manager" used for?', '["Managing Wi-Fi speed", "Storing and generating secure passwords", "Deleting old emails", "Speeding up your computer"]'::jsonb, 'Storing and generating secure passwords', 'It''s like a locked digital notebook that remembers all your passwords for you.'),
  ('easy', 'What is Wi-Fi for?', '["Wireless phone charging", "Connecting devices to the internet without cables", "Video calls only", "Remote printing"]'::jsonb, 'Connecting devices to the internet without cables', 'Wi-Fi is invisible "radio waves" that let your phone/laptop reach the internet without a cord.'),
  ('easy', 'What is "the cloud"?', '["A weather tool", "Storage and services accessed over the internet", "A computer virus", "A physical office server"]'::jsonb, 'Storage and services accessed over the internet', 'Think of it as a giant storage locker on the internet instead of on your own device.'),
  ('easy', 'What is a "chatbot"?', '["A house-cleaning robot", "A program that simulates conversation with users", "A computer virus", "A social media filter"]'::jsonb, 'A program that simulates conversation with users', 'It''s software that "talks" back to you, like a virtual customer service helper.'),
  ('easy', 'What is "spam" email?', '["Important work emails", "Unwanted or unsolicited messages", "Emails from your boss", "A type of email folder"]'::jsonb, 'Unwanted or unsolicited messages', 'Spam is junk mail nobody asked for, like ads or scams flooding your inbox.'),
  ('easy', 'What is a "smartphone app"?', '["A phone accessory", "A software program designed for mobile devices", "A phone repair service", "A type of SIM card"]'::jsonb, 'A software program designed for mobile devices', 'Apps are little programs, like Instagram or a calculator, that run on your phone.'),
  ('easy', 'What does a Wi-Fi password protect?', '["Your phone''s battery", "Unauthorized access to your network", "Your email inbox", "Your social media account"]'::jsonb, 'Unauthorized access to your network', 'It stops strangers from hopping onto your internet connection without permission.'),
  ('easy', 'What is "two-factor authentication" (2FA)?', '["Using two different passwords", "An extra security step beyond just a password", "Logging in twice a day", "A type of antivirus software"]'::jsonb, 'An extra security step beyond just a password', 'It''s like a second lock on the door — usually a code sent to your phone — after your password.'),
  ('easy', 'What does "download" mean?', '["Sending a file to someone", "Copying a file from the internet to your device", "Deleting a file", "Opening a file without saving it"]'::jsonb, 'Copying a file from the internet to your device', 'Downloading pulls something (like a photo or app) from online onto your own device.'),
  ('easy', 'What is a "browser" (like Chrome or Safari)?', '["A computer virus", "A program used to access websites", "A social media app", "A file storage device"]'::jsonb, 'A program used to access websites', 'It''s the tool you open to visit websites, like a window into the internet.'),
  ('easy', 'What does "USB" commonly refer to?', '["A type of Wi-Fi signal", "A connector/port used to plug in devices", "A video streaming service", "An operating system"]'::jsonb, 'A connector/port used to plug in devices', 'It''s the little rectangular plug you use to connect things like flash drives or chargers.'),
  ('easy', 'What is "streaming" (like Netflix or Spotify)?', '["Downloading a file permanently", "Playing content directly over the internet without saving it", "Deleting old files", "Sending large email attachments"]'::jsonb, 'Playing content directly over the internet without saving it', 'You''re watching or listening live over the internet instead of storing the file on your device.'),
  ('easy', 'What is artificial intelligence generally used for?', '["Only playing video games", "Performing tasks that typically require human thinking", "Only controlling robots", "Storing files online"]'::jsonb, 'Performing tasks that typically require human thinking', 'AI helps computers do "thinking" tasks, like recognizing faces or answering questions.'),
  ('easy', 'What does ChatGPT and similar tools mainly do?', '["Edit photos", "Generate human-like text responses to prompts", "Fix computer hardware", "Manage spreadsheets only"]'::jsonb, 'Generate human-like text responses to prompts', 'You type a question or request, and it writes back a human-sounding answer.'),
  ('easy', 'What is a "firewall" in basic terms?', '["A physical wall in a data center", "A security barrier that filters network traffic", "A type of email", "A backup storage device"]'::jsonb, 'A security barrier that filters network traffic', 'It''s like a security guard checking what''s allowed in and out of your network.'),
  ('easy', 'What does "update your software" mean?', '["Deleting the app", "Installing the newest version with fixes or features", "Uninstalling and reinstalling", "Changing your password"]'::jsonb, 'Installing the newest version with fixes or features', 'It''s like getting a patch that fixes bugs or adds new features to an app you already have.'),
  ('easy', 'What is "e-commerce"?', '["Sending emails to customers", "Buying and selling goods/services online", "A type of computer hardware", "A cybersecurity term"]'::jsonb, 'Buying and selling goods/services online', 'It''s shopping done over the internet, like buying shoes from an online store.'),
  ('easy', 'What is "screen time"?', '["Time for a screen to turn on", "Time spent using a phone, tablet, or computer", "Battery life of a device", "A phone repair setting"]'::jsonb, 'Time spent using a phone, tablet, or computer', 'It''s simply how long you spend looking at a screen each day.'),
  ('easy', 'What is video conferencing (like Zoom) used for?', '["Editing videos", "Holding meetings remotely via video and audio", "Storing video files", "Streaming movies"]'::jsonb, 'Holding meetings remotely via video and audio', 'It lets people talk face-to-face over the internet even when they''re far apart.'),
  ('easy', 'What does GPS help you do?', '["Browse the internet faster", "Determine your location and navigate", "Send text messages", "Charge your device"]'::jsonb, 'Determine your location and navigate', 'GPS uses satellites to tell your device (and you) exactly where you are and how to get somewhere.'),
  ('easy', 'What is a "digital footprint"?', '["A fingerprint scanner", "The trail of data you leave from online activity", "A type of malware", "A backup file"]'::jsonb, 'The trail of data you leave from online activity', 'It''s like footprints in sand, but online — every post, search, and click leaves a trace.'),
  ('easy', 'What does "sync" mean between devices?', '["Turning devices off", "Keeping data consistent and updated across devices", "Deleting duplicate files", "Charging multiple devices"]'::jsonb, 'Keeping data consistent and updated across devices', 'It means your photos, notes, or contacts match up automatically on your phone, tablet, and laptop.'),
  ('easy', 'What is "malware"?', '["A helpful software update", "Malicious software designed to harm or exploit devices", "A type of hardware", "A social media filter"]'::jsonb, 'Malicious software designed to harm or exploit devices', 'It''s the "bad guy" software — viruses, spyware, etc. — that tries to damage or steal from your device.'),
  ('easy', 'What does "AI-generated content" mean?', '["Content written entirely by humans", "Content produced by artificial intelligence tools", "Content that cannot be edited", "Content stored only on paper"]'::jsonb, 'Content produced by artificial intelligence tools', 'It''s text, images, or audio that an AI tool created, not a person typing it from scratch.'),
  ('easy', 'What is voice assistant technology (like Siri or Alexa)?', '["A human customer service agent", "Software that responds to voice commands", "A hearing aid device", "A phone repair app"]'::jsonb, 'Software that responds to voice commands', 'You talk to it, and it answers or performs a task, like setting a timer or playing music.'),
  ('easy', 'What does "backup" mean?', '["Deleting unnecessary files", "Making a copy of data in case the original is lost", "Restarting your device", "Compressing files to save space"]'::jsonb, 'Making a copy of data in case the original is lost', 'It''s like a safety copy of your photos or documents in case something goes wrong with the original.'),
  ('easy', 'What is a "QR code"?', '["A type of password", "A scannable code linking to information or a website", "A virus warning", "A Wi-Fi signal booster"]'::jsonb, 'A scannable code linking to information or a website', 'It''s that square pattern you scan with your phone camera to quickly open a link or menu.'),
  ('easy', 'What does "online privacy" mean?', '["Having no internet access", "Controlling who can see your personal information online", "Using a slow internet connection", "Deleting your email account"]'::jsonb, 'Controlling who can see your personal information online', 'It''s about deciding what personal info you share and who can see it online.'),
  ('easy', 'What is "automation" in the workplace?', '["Manually completing every task", "Using technology to perform tasks with minimal human input", "Hiring more staff", "Working from home"]'::jsonb, 'Using technology to perform tasks with minimal human input', 'It''s letting machines or software do repetitive tasks so people don''t have to do them by hand.'),
  ('easy', 'What does "PDF" represent?', '["A type of virus", "A common document file format", "A social media platform", "A video format"]'::jsonb, 'A common document file format', 'It''s a file type used for documents that look the same no matter what device opens them.'),
  ('easy', 'What is "machine learning" a part of?', '["Robotics only", "Artificial intelligence", "Hardware manufacturing", "Internet browsing"]'::jsonb, 'Artificial intelligence', 'It''s one of the main tools that makes AI possible, by letting computers learn from examples.'),
  ('easy', 'What is a "notification" on a device?', '["A type of virus", "An alert about an app, message, or update", "A backup process", "A password reset"]'::jsonb, 'An alert about an app, message, or update', 'It''s the little pop-up or buzz telling you something happened, like a new message.'),
  ('easy', 'What is an "e-signature"?', '["A printed signature", "A digital version of a signature used to sign documents online", "A type of email", "A password format"]'::jsonb, 'A digital version of a signature used to sign documents online', 'It lets you "sign" documents electronically instead of printing and signing by hand.'),
  ('easy', 'What does "trending" mean on social media?', '["Content that is broken", "Content gaining rapid popularity", "Content that has been deleted", "A type of advertisement"]'::jsonb, 'Content gaining rapid popularity', 'It means lots of people are suddenly talking about or sharing something.'),
  ('easy', 'What is a "data breach"?', '["A software update", "Unauthorized access to confidential information", "A slow internet connection", "A type of backup"]'::jsonb, 'Unauthorized access to confidential information', 'It''s when hackers or unauthorized people get into private information they shouldn''t see.'),
  ('easy', 'What does "AI bias" mean?', '["AI that only works on weekends", "AI systems producing unfair outcomes due to skewed data", "AI that is too slow", "AI that cannot connect to Wi-Fi"]'::jsonb, 'AI systems producing unfair outcomes due to skewed data', 'If the information used to teach an AI is unfair or incomplete, the AI''s answers can end up unfair too.'),
  ('easy', 'What enables "remote work"?', '["Only landline phones", "Internet-based tools like video calls, cloud storage, and messaging apps", "Fax machines only", "Physical mail"]'::jsonb, 'Internet-based tools like video calls, cloud storage, and messaging apps', 'Tools like Zoom, email, and shared drives let people work from anywhere with internet access.'),
  ('easy', 'What does a "subscription model" mean for software?', '["A one-time purchase", "Paying a recurring fee (monthly/yearly) for access", "A free trial only", "A type of hardware warranty"]'::jsonb, 'Paying a recurring fee (monthly/yearly) for access', 'Instead of paying once, you pay a little regularly (like Netflix) to keep using the service.'),
  ('easy', 'What is "phishing"?', '["A type of online game", "A scam trying to trick people into revealing personal information", "A method of backing up files", "A social media feature"]'::jsonb, 'A scam trying to trick people into revealing personal information', 'Scammers send fake emails or messages pretending to be trustworthy to steal your info.'),
  ('medium', 'What''s the difference between "AI" and "machine learning"?', '["They are exactly the same thing", "Machine learning is a subset of AI that learns from data", "AI is a subset of machine learning", "Machine learning only applies to robots"]'::jsonb, 'Machine learning is a subset of AI that learns from data', 'Think of AI as the big umbrella idea ("smart machines"), and machine learning as one tool under that umbrella that learns from examples.'),
  ('medium', 'What is "generative AI"?', '["AI that only analyzes numbers", "AI that creates new content like text, images, or audio", "AI that repairs hardware", "AI used exclusively in manufacturing"]'::jsonb, 'AI that creates new content like text, images, or audio', 'It''s AI that *makes* new things, like writing a story or creating a picture from scratch.'),
  ('medium', 'What is a "large language model" (LLM)?', '["A large physical computer", "An AI system trained on vast text data to understand and generate language", "A translation dictionary", "A type of spreadsheet software"]'::jsonb, 'An AI system trained on vast text data to understand and generate language', 'It''s an AI that has "read" enormous amounts of text so it can understand and write language naturally.'),
  ('medium', 'What does "API" stand for and do?', '["Application Programming Interface — lets software systems communicate", "A type of antivirus", "A password protocol", "A file storage format"]'::jsonb, 'Application Programming Interface — lets software systems communicate', 'It''s like a waiter taking your order between two apps, letting them "talk" and share information.'),
  ('medium', 'What is "SaaS" (Software as a Service)?', '["Software installed only on physical CDs", "Software delivered over the internet on a subscription basis", "A hardware repair service", "A type of computer virus"]'::jsonb, 'Software delivered over the internet on a subscription basis', 'You access the software online (like Gmail) instead of installing it from a disc, usually paying regularly.'),
  ('medium', 'What does a data privacy regulation (like GDPR) govern?', '["Internet speed limits", "How companies collect, use, and protect personal data", "Software pricing", "Hardware manufacturing standards"]'::jsonb, 'How companies collect, use, and protect personal data', 'These are laws making sure companies handle your personal information responsibly and with your consent.'),
  ('medium', 'What is "cybersecurity risk assessment"?', '["Checking Wi-Fi signal strength", "Evaluating potential vulnerabilities and threats to digital systems", "Reviewing employee salaries", "A type of software update"]'::jsonb, 'Evaluating potential vulnerabilities and threats to digital systems', 'It''s like a health checkup for your company''s computer systems, looking for weak spots hackers could exploit.'),
  ('medium', 'What does "AI hallucination" mean?', '["AI systems experiencing visual glitches", "AI generating false or fabricated information confidently", "AI crashing due to overheating", "AI refusing to respond"]'::jsonb, 'AI generating false or fabricated information confidently', 'Sometimes AI confidently makes up facts or details that sound real but aren''t true — like a "confident guess" that''s wrong.'),
  ('medium', 'Why is "cloud computing" valuable for businesses?', '["Reducing the need for physical office space only", "Scalable, on-demand computing resources without owning hardware", "Eliminating the need for internet access", "Replacing all employees"]'::jsonb, 'Scalable, on-demand computing resources without owning hardware', 'Businesses can "rent" computing power as needed instead of buying and maintaining expensive servers.'),
  ('medium', 'What is "digital transformation" for a company?', '["Rebranding a company logo", "Integrating digital technology into all areas of business operations", "Switching to a paper-based system", "Hiring only IT staff"]'::jsonb, 'Integrating digital technology into all areas of business operations', 'It means using technology to fundamentally change how a business works, not just adding a few gadgets.'),
  ('medium', 'What is "prompt engineering"?', '["Building physical AI hardware", "Crafting effective inputs/questions to get better AI outputs", "Repairing broken software", "A type of network cable installation"]'::jsonb, 'Crafting effective inputs/questions to get better AI outputs', 'It''s the skill of asking AI tools the right way so you get better, more useful answers.'),
  ('medium', 'What does "algorithm" mean?', '["A type of virus", "A set of rules or steps a computer follows to complete a task", "A hardware component", "A social media trend"]'::jsonb, 'A set of rules or steps a computer follows to complete a task', 'Think of it like a recipe: step-by-step instructions telling the computer exactly what to do.'),
  ('medium', 'What is "encryption"?', '["Deleting files permanently", "Converting data into a coded format to prevent unauthorized access", "Compressing files to save space", "A type of Wi-Fi signal"]'::jsonb, 'Converting data into a coded format to prevent unauthorized access', 'It scrambles your information into a secret code so only the right person can unlock and read it.'),
  ('medium', 'What does "ROI on AI investment" measure?', '["The speed of internet connection", "The value/return gained compared to the cost of implementing AI", "The number of AI tools purchased", "Employee satisfaction only"]'::jsonb, 'The value/return gained compared to the cost of implementing AI', 'It''s basically asking: "Did the money spent on AI actually pay off in results?"'),
  ('medium', 'What is "automation bias"?', '["Preferring manual tasks over automated ones", "Over-relying on automated systems even when they''re wrong", "A type of computer virus", "A hardware malfunction"]'::jsonb, 'Over-relying on automated systems even when they''re wrong', 'It''s when people trust a computer''s answer too much, even if it''s actually a mistake.'),
  ('medium', 'What does "on-premise" software mean?', '["Software accessed only via mobile apps", "Software installed and run on a company''s own servers/computers", "Free software with no cost", "Software that cannot be updated"]'::jsonb, 'Software installed and run on a company''s own servers/computers', 'It means the company keeps and runs the software on their own physical machines, instead of using the cloud.'),
  ('medium', 'Structured vs. unstructured data — what''s the difference?', '["There is no difference", "Structured data is organized (like spreadsheets); unstructured is not (like emails, images)", "Structured data is always larger", "Unstructured data cannot be stored digitally"]'::jsonb, 'Structured data is organized (like spreadsheets); unstructured is not (like emails, images)', 'Structured data fits neatly into rows and columns; unstructured data (like a photo or a paragraph) doesn''t follow a fixed format.'),
  ('medium', 'What does "AI ethics" address?', '["How fast AI can process data", "Fairness, accountability, and responsible use of AI systems", "The cost of AI software", "The physical design of AI hardware"]'::jsonb, 'Fairness, accountability, and responsible use of AI systems', 'It''s about making sure AI is used in ways that are fair, safe, and don''t harm people.'),
  ('medium', 'What is a "digital twin"?', '["A backup email account", "A virtual model/replica of a physical object or process", "A type of two-factor authentication", "A duplicate social media account"]'::jsonb, 'A virtual model/replica of a physical object or process', 'It''s like a computer simulation copy of something real, like a factory machine, used to test and predict how it behaves.'),
  ('medium', 'What does "scalability" mean for a tech solution?', '["The ability to shrink a company", "The ability to handle growth without major redesign", "The physical size of servers", "A type of pricing discount"]'::jsonb, 'The ability to handle growth without major redesign', 'A scalable system can handle more users or work without falling apart or needing to be completely rebuilt.'),
  ('medium', 'What is "IoT" (Internet of Things)?', '["A social media platform", "A network of physical devices connected and sharing data via the internet", "A type of antivirus software", "A programming language"]'::jsonb, 'A network of physical devices connected and sharing data via the internet', 'It''s everyday objects — like smart thermostats or fitness trackers — connected to the internet and talking to each other.'),
  ('medium', 'What does "AI model training" involve?', '["Physically assembling computer hardware", "Feeding data to an algorithm so it can learn patterns", "Installing software updates", "Setting up a Wi-Fi router"]'::jsonb, 'Feeding data to an algorithm so it can learn patterns', 'It''s like teaching a student with lots of practice examples until the AI "gets" the pattern.'),
  ('medium', 'What is "vendor lock-in"?', '["A type of cybersecurity attack", "Difficulty switching providers due to dependency on their systems", "A hardware warranty term", "A software free trial period"]'::jsonb, 'Difficulty switching providers due to dependency on their systems', 'It''s getting so dependent on one company''s tools that switching to a competitor becomes difficult or costly.'),
  ('medium', 'What does "latency" mean?', '["The storage capacity of a device", "The delay between an action and its response", "The battery life of a device", "The number of users on a platform"]'::jsonb, 'The delay between an action and its response', 'It''s the little lag you notice, like when you click something and it takes a moment to load.'),
  ('medium', 'What is "predictive analytics"?', '["Guessing randomly about future trends", "Using historical data and statistics to forecast future outcomes", "A type of antivirus scan", "A social media algorithm only"]'::jsonb, 'Using historical data and statistics to forecast future outcomes', 'It looks at past patterns (like past sales) to make an educated guess about what will happen next.'),
  ('medium', 'What does "no-code/low-code" mean?', '["Software with no functionality", "Tools that let people build applications with minimal or no programming", "Free software only", "Outdated software systems"]'::jsonb, 'Tools that let people build applications with minimal or no programming', 'These tools use drag-and-drop and simple menus so people who aren''t programmers can still build apps or automations.'),
  ('medium', 'What is a "data lake"?', '["A physical body of water near data centers", "A centralized repository storing raw data in its native format", "A type of firewall", "A backup email service"]'::jsonb, 'A centralized repository storing raw data in its native format', 'It''s like a giant digital storage pool where all kinds of raw, unorganized data get dumped and kept until needed.'),
  ('medium', 'What does "AI governance" involve?', '["Government-run AI companies only", "Policies and frameworks for responsible AI development and use", "The physical location of servers", "Employee training on Excel"]'::jsonb, 'Policies and frameworks for responsible AI development and use', 'It''s the rulebook organizations create to make sure AI is developed and used responsibly and safely.'),
  ('medium', 'Is multi-factor authentication risk-free?', '["It is always 100% secure with no risk", "It can still be bypassed through social engineering or device theft", "It only works on desktop computers", "It eliminates the need for passwords entirely"]'::jsonb, 'It can still be bypassed through social engineering or device theft', 'Even with extra security steps, clever scammers or stolen devices can sometimes still get through.'),
  ('medium', 'What is "technical debt"?', '["Money owed to a software vendor", "The implied cost of shortcuts taken in system design that need fixing later", "A loan for buying computer hardware", "Unpaid employee salaries in IT"]'::jsonb, 'The implied cost of shortcuts taken in system design that need fixing later', 'It''s like taking a shortcut now that creates extra work later — the "debt" you''ll eventually have to pay off by fixing it properly.'),
  ('medium', 'What is "edge computing"?', '["Computing done only in large data centers", "Processing data closer to where it''s generated rather than in a centralized cloud", "A type of extreme sports app", "A cybersecurity certification"]'::jsonb, 'Processing data closer to where it''s generated rather than in a centralized cloud', 'Instead of sending data far away to a central computer, it''s processed nearby (like directly on a smart camera) for faster results.'),
  ('medium', 'What does "AI transparency" mean?', '["AI systems being invisible to users", "Understanding how and why an AI system makes decisions", "Free access to all AI tools", "AI that runs without electricity"]'::jsonb, 'Understanding how and why an AI system makes decisions', 'It''s about being able to see and understand the reasoning behind an AI''s decision, not just getting an answer with no explanation.'),
  ('medium', 'What is "single sign-on" (SSO)?', '["A system requiring a new password for every app", "One login granting access to multiple applications", "A type of firewall", "A backup power system"]'::jsonb, 'One login granting access to multiple applications', 'You log in once, and it unlocks several different apps or tools without needing separate passwords each time.'),
  ('medium', 'What does "data governance" mean?', '["Physical security guards for server rooms", "Policies managing data availability, usability, integrity, and security", "Government regulation of the internet", "Employee vacation policies"]'::jsonb, 'Policies managing data availability, usability, integrity, and security', 'It''s the set of internal rules a company follows to make sure its data is accurate, safe, and used properly.'),
  ('medium', 'What is "synthetic data"?', '["Real customer data collected without consent", "Artificially generated data used to train models without exposing real data", "Data that cannot be used by computers", "A type of computer virus"]'::jsonb, 'Artificially generated data used to train models without exposing real data', 'It''s fake but realistic-looking data created by computers, used to train AI safely without risking real people''s private information.'),
  ('medium', 'What does "AI model drift" mean?', '["AI physically moving location", "An AI model''s performance degrading over time as real-world data changes", "A software installation error", "A type of network outage"]'::jsonb, 'An AI model''s performance degrading over time as real-world data changes', 'Over time, the real world changes, and an AI trained on old information can become less accurate — like using an outdated map.'),
  ('medium', 'What is "zero trust security"?', '["Trusting all internal network traffic by default", "A model that verifies every user/device, trusting nothing by default", "Not using any security measures", "A type of free antivirus software"]'::jsonb, 'A model that verifies every user/device, trusting nothing by default', 'Instead of assuming anyone "inside" the network is safe, every single access request gets checked and verified.'),
  ('medium', 'What does a "business intelligence (BI) tool" do?', '["Only sends emails", "Analyzes business data to support decision-making", "Manages employee payroll only", "Repairs computer hardware"]'::jsonb, 'Analyzes business data to support decision-making', 'It turns raw business numbers into charts and insights, helping leaders make smarter decisions.'),
  ('medium', 'What is "AI augmentation"?', '["AI completely replacing human workers", "AI assisting and enhancing human decision-making, not replacing it", "AI that only works on weekends", "A type of hardware upgrade"]'::jsonb, 'AI assisting and enhancing human decision-making, not replacing it', 'It''s AI working *alongside* people, like a helpful assistant, rather than taking over their job entirely.'),
  ('medium', 'What does "interoperability" mean between software systems?', '["Systems that cannot communicate with each other", "The ability of different systems to work together and exchange data", "A type of cybersecurity threat", "Software that only works offline"]'::jsonb, 'The ability of different systems to work together and exchange data', 'It''s when different programs, even from different companies, can share information smoothly with each other.'),
  ('hard', 'Supervised vs. unsupervised machine learning — what''s the difference?', '["Supervised learning uses labeled data; unsupervised finds patterns in unlabeled data", "Supervised learning requires no data at all", "Unsupervised learning is always more accurate", "There is no real difference"]'::jsonb, 'Supervised learning uses labeled data; unsupervised finds patterns in unlabeled data', 'Supervised learning is like studying with an answer key (labeled examples); unsupervised learning is like finding patterns without any answer key at all.'),
  ('hard', 'What does "explainable AI" (XAI) aim to solve?', '["Making AI faster", "Making AI decision-making processes understandable to humans", "Reducing AI''s electricity usage", "Eliminating the need for data"]'::jsonb, 'Making AI decision-making processes understandable to humans', 'It tries to open up the "black box" so humans can understand *why* an AI made a certain decision.'),
  ('hard', 'What is a "foundation model" in AI?', '["A model trained only on one narrow task", "A large, general-purpose model trained on broad data, adaptable to many tasks", "The first computer chip ever made", "A physical server foundation"]'::jsonb, 'A large, general-purpose model trained on broad data, adaptable to many tasks', 'It''s like a well-rounded generalist that can be adapted for many different jobs, rather than being built for just one narrow task.'),
  ('hard', 'What does "overfitting" mean?', '["A model that generalizes well to new data", "A model that performs well on training data but poorly on new, unseen data", "A model that is too simple", "A hardware compatibility issue"]'::jsonb, 'A model that performs well on training data but poorly on new, unseen data', 'It''s like memorizing answers to practice questions instead of actually understanding the subject — great on practice, bad on the real test.'),
  ('hard', 'What is "differential privacy"?', '["Giving different passwords to different users", "A technique to share data insights while protecting individual privacy", "A type of firewall", "A method of speeding up internet connections"]'::jsonb, 'A technique to share data insights while protecting individual privacy', 'It adds a bit of statistical "noise" to data so patterns can still be studied without exposing any one person''s private details.'),
  ('hard', 'What does "reinforcement learning" involve?', '["Learning from labeled examples only", "An agent learning by receiving rewards/penalties based on actions", "Memorizing a fixed dataset", "Manually programming every decision"]'::jsonb, 'An agent learning by receiving rewards/penalties based on actions', 'It''s like training a pet with treats: the AI tries actions and learns from rewards or penalties which ones work best.'),
  ('hard', 'What is the "black box problem" in AI?', '["AI systems being physically stored in black servers", "The difficulty in understanding how complex models arrive at decisions", "A type of hardware failure", "AI systems that cannot connect to the internet"]'::jsonb, 'The difficulty in understanding how complex models arrive at decisions', 'Some AI systems are so complex that even their creators can''t fully explain exactly why they gave a specific answer.'),
  ('hard', 'What does "AI alignment" refer to?', '["Physically aligning computer hardware", "Ensuring AI systems act in accordance with human values and intentions", "Syncing AI across multiple devices", "A type of screen calibration"]'::jsonb, 'Ensuring AI systems act in accordance with human values and intentions', 'It''s making sure AI actually does what humans truly want and intend, not something unintended or harmful.'),
  ('hard', 'What is "federated learning"?', '["Training a model on centralized data only", "Training a model across decentralized devices without sharing raw data", "A government AI regulation", "A type of cloud storage pricing"]'::jsonb, 'Training a model across decentralized devices without sharing raw data', 'Multiple devices (like phones) learn together and share only what they learned, not the actual private data itself.'),
  ('hard', 'What does "tokenization" mean for large language models?', '["Creating cryptocurrency", "Breaking text into smaller units (tokens) for the model to process", "Encrypting a password", "Compressing an image file"]'::jsonb, 'Breaking text into smaller units (tokens) for the model to process', 'The AI chops up sentences into small chunks (like words or parts of words) so it can process and understand them piece by piece.'),
  ('hard', 'What is a "hallucination guardrail" in AI systems?', '["A physical barrier around servers", "Techniques/checks designed to reduce false or fabricated AI outputs", "A type of firewall for networks", "A password requirement"]'::jsonb, 'Techniques/checks designed to reduce false or fabricated AI outputs', 'It''s a safety check built in to catch or reduce the AI confidently making up false information.'),
  ('hard', 'What does "model interpretability" trade off against?', '["Cost of hardware", "Model complexity/performance — simpler models are often more interpretable", "Internet speed", "The number of users"]'::jsonb, 'Model complexity/performance — simpler models are often more interpretable', 'Often, the more powerful and complex a model is, the harder it becomes to understand exactly how it reaches its answers.'),
  ('hard', 'What is "shadow IT"?', '["IT staff working night shifts", "Technology used within an organization without official approval or oversight", "A backup data center", "A type of malware"]'::jsonb, 'Technology used within an organization without official approval or oversight', 'It''s when employees use apps or tools the IT department doesn''t know about or hasn''t approved — like using a personal file-sharing app for work files.'),
  ('hard', 'What does "AI red-teaming" involve?', '["Assigning AI projects to a specific team color", "Deliberately testing AI systems for weaknesses, biases, or harmful outputs", "A marketing strategy", "A type of software licensing"]'::jsonb, 'Deliberately testing AI systems for weaknesses, biases, or harmful outputs', 'It''s like hiring "ethical hackers" to intentionally try to break or trick an AI system so its weaknesses can be fixed before real problems happen.'),
  ('hard', 'What is a "vector database" used for in AI?', '["Storing spreadsheets only", "Storing data as numerical representations for efficient similarity search (used in AI search/retrieval)", "A type of antivirus software", "Managing employee schedules"]'::jsonb, 'Storing data as numerical representations for efficient similarity search (used in AI search/retrieval)', 'It stores information in a special numeric format so AI can quickly find things that are conceptually "similar," not just exact matches.'),
  ('hard', 'What does "retrieval-augmented generation" (RAG) do?', '["Generates random data", "Combines AI generation with retrieval of external, relevant information to improve accuracy", "Deletes outdated AI models", "Speeds up internet browsing"]'::jsonb, 'Combines AI generation with retrieval of external, relevant information to improve accuracy', 'Before answering, the AI first looks up relevant real information (like searching a library), then uses that to write a more accurate response.'),
  ('hard', 'What is "algorithmic accountability"?', '["Algorithms tracking financial accounts", "Holding organizations responsible for the outcomes/impacts of their algorithms", "A type of software billing system", "A cybersecurity certification"]'::jsonb, 'Holding organizations responsible for the outcomes/impacts of their algorithms', 'It means companies must own up to and fix problems caused by their automated systems, not just blame "the algorithm."'),
  ('hard', 'What does "model fine-tuning" mean?', '["Building an AI model from scratch every time", "Further training a pre-existing model on specific, narrower data for a specialized task", "Adjusting the volume of AI voice assistants", "Repairing broken hardware"]'::jsonb, 'Further training a pre-existing model on specific, narrower data for a specialized task', 'It''s like taking a well-rounded graduate and giving them extra specialized training for one specific job.'),
  ('hard', 'What is the concern with "data poisoning" attacks on AI?', '["Physically contaminating server rooms", "Intentionally corrupting training data to manipulate an AI model''s behavior", "Overloading a network with traffic", "Stealing hardware"]'::jsonb, 'Intentionally corrupting training data to manipulate an AI model''s behavior', 'Attackers sneak bad or misleading data into the training process so the AI learns the wrong lessons on purpose.'),
  ('hard', 'What does "AI observability" mean for organizations?', '["Watching employees work", "Monitoring AI system performance, behavior, and outputs in real time", "A type of physical security camera", "A software licensing model"]'::jsonb, 'Monitoring AI system performance, behavior, and outputs in real time', 'It''s like a dashboard that lets a company keep an eye on how their AI is behaving and performing after it''s deployed.'),
  ('hard', 'What is "prompt injection" as a security concern?', '["A medical procedure", "Manipulating an AI system''s behavior through crafted malicious inputs", "A hardware upgrade process", "A type of network cable"]'::jsonb, 'Manipulating an AI system''s behavior through crafted malicious inputs', 'It''s like tricking the AI with cleverly worded instructions hidden in a message, getting it to do something it shouldn''t.'),
  ('hard', 'What does a "model card" typically provide?', '["A credit card for purchasing AI tools", "Details on a model''s intended use, limitations, and performance", "A physical ID badge", "A discount coupon"]'::jsonb, 'Details on a model''s intended use, limitations, and performance', 'It''s like a nutrition label for an AI model, explaining what it''s good at, its limits, and how it was tested.'),
  ('hard', 'Narrow AI vs. general AI (AGI) — what''s the difference?', '["There is no difference", "Narrow AI performs specific tasks; general AI would match human-level intelligence across domains", "Narrow AI is always more powerful", "General AI already exists and is widely deployed"]'::jsonb, 'Narrow AI performs specific tasks; general AI would match human-level intelligence across domains', 'Narrow AI is like a specialist good at one job (like chess or translation); general AI, still theoretical, would be like a human — capable across nearly everything.'),
  ('hard', 'What does "chain-of-thought prompting" encourage an AI to do?', '["Respond as briefly as possible", "Break down reasoning into intermediate steps before answering", "Generate images instead of text", "Connect to multiple databases simultaneously"]'::jsonb, 'Break down reasoning into intermediate steps before answering', 'It''s like asking the AI to "show its work" step-by-step, similar to how a student solves a math problem, which often leads to better answers.'),
  ('hard', 'What does "compute" refer to regarding AI development costs?', '["The number of employees at a company", "The processing power (hardware resources) needed to train/run AI models", "A type of software license", "Internet bandwidth only"]'::jsonb, 'The processing power (hardware resources) needed to train/run AI models', 'Training powerful AI models takes an enormous amount of computer processing power, which costs real money — that''s "compute."'),
  ('hard', 'What does "data lineage" track?', '["Employee family trees", "The origin, movement, and transformation of data through systems", "A type of network cable path", "Software version history only"]'::jsonb, 'The origin, movement, and transformation of data through systems', 'It''s like a family tree, but for data — tracing where information came from and how it changed as it moved through systems.'),
  ('hard', 'What is a "guardrail" in enterprise AI deployment?', '["A physical safety rail", "Rules/constraints built into a system to keep AI outputs within safe, intended boundaries", "A type of firewall hardware", "A backup power supply"]'::jsonb, 'Rules/constraints built into a system to keep AI outputs within safe, intended boundaries', 'It''s like bumper lanes in bowling — rules built in to keep the AI''s responses on track and prevent harmful or off-limits outputs.'),
  ('hard', 'What does "AI model versioning" allow organizations to do?', '["Track and manage different iterations of an AI model over time", "Delete old software permanently", "Increase internet speed", "Reduce the number of employees needed"]'::jsonb, 'Track and manage different iterations of an AI model over time', 'It keeps a record of each update to a model, like save points in a game, so teams can track changes or roll back if needed.'),
  ('hard', 'What is "synthetic media" (like deepfakes) primarily created using?', '["Traditional photography only", "AI techniques that generate realistic but fabricated images, audio, or video", "Manual video editing without AI", "Physical special effects only"]'::jsonb, 'AI techniques that generate realistic but fabricated images, audio, or video', 'AI learns from real footage/audio and then generates entirely fake but very realistic-looking content of people saying or doing things they never actually did.'),
  ('hard', 'What does "context window" mean for large language models?', '["A physical monitor size", "The amount of text/information a model can consider at once when generating a response", "The number of users allowed", "A type of software subscription"]'::jsonb, 'The amount of text/information a model can consider at once when generating a response', 'It''s like the model''s short-term memory — how much text it can "see" and remember at one time while forming an answer.'),
  ('hard', 'What is "AI model bias auditing"?', '["Checking a model''s electricity consumption", "Systematically evaluating a model for unfair or discriminatory outcomes", "Reviewing employee performance", "A type of hardware inspection"]'::jsonb, 'Systematically evaluating a model for unfair or discriminatory outcomes', 'It''s a careful check to see if an AI is treating certain groups of people unfairly, often without anyone intending it to.'),
  ('hard', 'What does "human-in-the-loop" (HITL) mean?', '["AI operating with zero human involvement", "Incorporating human review/oversight into AI decision-making processes", "A type of network topology", "A hardware assembly process"]'::jsonb, 'Incorporating human review/oversight into AI decision-making processes', 'A person double-checks or approves the AI''s decisions at key points, rather than letting the AI act completely alone.'),
  ('hard', 'How is "quantum computing" fundamentally different from classical computing?', '["It only runs on smartphones", "It uses quantum bits (qubits) that can represent multiple states simultaneously, unlike classical binary bits", "It cannot process any data", "It is identical to classical computing but faster"]'::jsonb, 'It uses quantum bits (qubits) that can represent multiple states simultaneously, unlike classical binary bits', 'Normal computers use bits that are either 0 or 1; quantum computers use qubits that can be a mix of both at once, allowing very different types of calculations.'),
  ('hard', 'What does AI regulatory compliance (like the EU AI Act) generally require for high-risk systems?', '["No requirements exist for AI systems", "Risk assessments, transparency, and documentation depending on risk classification", "Banning all AI use", "Only applies to government agencies"]'::jsonb, 'Risk assessments, transparency, and documentation depending on risk classification', 'Higher-risk AI uses (like in healthcare or hiring) face stricter requirements to prove they''re safe, documented, and transparent.'),
  ('hard', 'What is "catastrophic forgetting" in machine learning?', '["A hardware failure", "A model losing previously learned information when trained on new data", "A type of data breach", "A network outage"]'::jsonb, 'A model losing previously learned information when trained on new data', 'It''s like learning a new skill so intensely that you accidentally forget an old one — the model overwrites old knowledge when learning something new.'),
  ('hard', 'What does "model distillation" achieve?', '["Making a model physically smaller in size only", "Training a smaller, efficient model to mimic a larger model''s behavior", "Deleting unnecessary training data", "Encrypting model outputs"]'::jsonb, 'Training a smaller, efficient model to mimic a larger model''s behavior', 'It''s like teaching a "mini version" of a big expert model so it behaves similarly but runs faster and cheaper.'),
  ('hard', 'Open-source vs. closed-source AI models — what''s significant for businesses?', '["There is no practical difference", "Open-source offers more customization/transparency; closed-source often offers more support/polish, with trade-offs in each", "Open-source is always illegal to use", "Closed-source models are always free"]'::jsonb, 'Open-source offers more customization/transparency; closed-source often offers more support/polish, with trade-offs in each', 'Open-source is like a car you can fully customize yourself; closed-source is more like a fully serviced rental — each has its pros and cons.'),
  ('hard', 'What does "AI supply chain risk" refer to?', '["Physical shipping delays for hardware only", "Vulnerabilities introduced through third-party data, models, or tools used to build an AI system", "A type of cybersecurity insurance", "Employee turnover in IT departments"]'::jsonb, 'Vulnerabilities introduced through third-party data, models, or tools used to build an AI system', 'If any outside data, tool, or model your AI relies on has a flaw or is compromised, it can create risk for your whole system, like a weak link in a chain.'),
  ('hard', 'What is "differential access control" in enterprise AI systems?', '["Giving every employee the same level of access", "Restricting AI system capabilities/data access based on user roles and permissions", "A type of internet speed throttling", "A backup scheduling system"]'::jsonb, 'Restricting AI system capabilities/data access based on user roles and permissions', 'Different employees get different levels of access based on their job — like how not everyone at a company can see payroll data.'),
  ('hard', 'What does "responsible AI scaling" primarily balance?', '["Only maximizing profit regardless of risk", "Growing AI capability and deployment while managing safety, ethical, and societal risks", "Reducing all AI development to zero", "Increasing hardware costs only"]'::jsonb, 'Growing AI capability and deployment while managing safety, ethical, and societal risks', 'It''s about growing and expanding AI use thoughtfully, making sure safety and ethics keep pace with how powerful and widespread the technology becomes.');
insert into scenario_quiz_questions (difficulty, question_text, answer, explanation)
values
  ('easy', 'You receive a 40-page client report and have 10 minutes before a meeting. How could AI help you prepare quickly?', 'Use AI to summarize the report.', 'AI can read the long report and give you the important points, like a friend giving you the short version of a long story.'),
  ('easy', 'You have 500 customer comments in Excel and need to understand the most common complaints. What approach would you use?', 'Use AI to group similar comments.', 'AI can put complaints about the same thing into groups so you can quickly see the biggest problems.'),
  ('easy', 'Your manager sends you a long email thread and asks, “What did we finally decide?” How could AI help?', 'Ask AI to summarize the email thread and decisions.', 'Instead of reading every message, AI can tell you what everyone finally agreed on.'),
  ('easy', 'You need to write a professional follow-up email after a client meeting. How would you use AI effectively?', 'Give AI the meeting context and ask it to draft the email.', 'Tell AI what happened and what you want to say. It can create a first draft, which you should check before sending.'),
  ('easy', 'You have meeting notes containing several tasks assigned to different people. How could AI help organize them?', 'Ask AI to extract tasks, owners and deadlines.', 'AI can turn messy notes into a simple list of what needs to happen, who will do it, and by when.'),
  ('easy', 'Your Excel sheet contains duplicate customer records. What should you do to identify or remove them?', 'Use Excel''s Remove Duplicates or data-cleaning tools.', 'Excel can find repeated records for you instead of you searching through hundreds of rows.'),
  ('easy', 'You need to explain a technical AI concept to a non-technical client. How could AI help you simplify it?', 'Ask AI to explain it in plain language with an example.', 'AI can turn complicated tech words into normal everyday language.'),
  ('easy', 'Your manager gives you sales data and asks which month performed best. What would you do first?', 'Compare sales by month.', 'Organize the numbers month by month, then find the month with the highest sales.'),
  ('easy', 'You have a recorded meeting and don''t have time to listen to the full hour. How could technology help?', 'Use transcription and AI summarization.', 'Technology can turn the meeting audio into words and then give you the important points.'),
  ('easy', 'You repeatedly create the same weekly status report using updated numbers. What could you automate?', 'Automate data collection and report creation.', 'If you do the same steps every week, a computer can often repeat those steps for you.'),
  ('easy', 'You need to compare two versions of a policy document. How could AI make this easier?', 'Use an AI or document comparison tool.', 'The tool can read both documents and show what was added, removed or changed.'),
  ('easy', 'You have customer names, email addresses and phone numbers in separate Excel columns. What type of task is this: data cleaning, analysis or prediction?', 'Data cleaning.', 'You''re fixing and organizing the data before studying it, like cleaning your desk before homework.'),
  ('easy', 'You need ideas for the agenda of a client workshop tomorrow. How could generative AI help?', 'Give AI the workshop goal and ask for agenda ideas.', 'Tell AI what the meeting is about and who is attending. It can suggest useful topics and activities.'),
  ('easy', 'You have a spreadsheet with thousands of rows and want to quickly find only “High Risk” cases. What Excel capability would help?', 'Use Excel filters.', 'A filter can show only the rows marked High Risk and hide everything else.'),
  ('easy', 'Your manager asks you to turn a detailed report into five presentation bullets. What could you ask AI to do?', 'Ask AI to summarize it into five presentation points.', 'AI can shrink a big report into a few important ideas that are easier to present.'),
  ('easy', 'You have to send similar personalized emails to 50 clients. How might you reduce the manual work?', 'Use templates plus mail merge or automation.', 'Write the main message once, then technology can change things like each customer''s name automatically.'),
  ('easy', 'A client uses a technical term you''ve never heard before during a call. How could you quickly understand it after the meeting?', 'Ask AI to explain the term with an example.', 'Give AI the confusing word and ask it to explain it like you''re a beginner.'),
  ('easy', 'You need to translate a client email from another language. What type of AI capability could help?', 'Use AI translation.', 'AI can change text from one language into another while keeping the meaning.'),
  ('easy', 'You want to create a chart showing how monthly revenue has changed over one year. What type of chart would you choose?', 'Line chart.', 'A line chart is good for showing how something goes up or down over time.'),
  ('easy', 'You have a PDF contract and need to locate all references to “termination.” What''s the quickest technology-assisted approach?', 'Search the PDF or ask a document AI tool.', 'Search for the word and jump directly to the relevant parts instead of reading every page.'),
  ('easy', 'You have written a client update but aren''t confident about its tone. How could AI help before you send it?', 'Ask AI to review the tone.', 'AI can tell you if your message sounds too harsh, too casual or unclear and suggest improvements.'),
  ('easy', 'Your team keeps answering the same internal process questions repeatedly. What kind of AI solution might help?', 'An internal AI knowledge assistant or chatbot.', 'Give the chatbot approved company information so employees can ask it common questions.'),
  ('easy', 'You need to convert messy meeting notes into structured minutes. What should you ask an AI assistant to produce?', 'Structured meeting minutes.', 'Ask AI to organize notes into decisions, discussion points, tasks, owners and deadlines.'),
  ('easy', 'Your manager asks for the average value of 200 transactions in Excel. What should you use instead of calculating manually?', 'Use the AVERAGE formula.', 'Excel can calculate the average automatically.'),
  ('easy', 'You receive a CSV file but normally work in Excel. Can the data still be opened and analyzed?', 'Yes. Open or import the CSV into Excel.', 'A CSV is another way of storing rows and columns. Excel can read it.'),
  ('easy', 'You need a first draft of a client presentation but already know the key points. How could AI speed up the process?', 'Ask AI to create a first draft or outline.', 'Give AI your important points and let it organize them. You then improve the final presentation.'),
  ('easy', 'You want to know whether customer complaints are mostly positive, negative or neutral. What AI technique could help?', 'Sentiment analysis.', 'AI can sort comments into feelings such as positive, negative or neutral.'),
  ('easy', 'You have inconsistent entries such as “Delhi,” “New Delhi,” and “DELHI” in your dataset. What needs to happen before analysis?', 'Standardize and clean the data.', 'These entries may mean the same place, so clean them before counting or comparing.'),
  ('easy', 'Your team manually copies information from one spreadsheet to another every Friday. What should you consider automating?', 'Automate the repetitive data transfer.', 'Software can probably do much of this repeated copying automatically.'),
  ('easy', 'An AI tool gives you a statistic for a client presentation. What should you do before using it?', 'Verify the statistic and its source.', 'AI can make mistakes. Check important numbers before showing them to your client.'),
  ('medium', 'Your client has 10,000 customer complaints and wants to understand the major reasons customers are unhappy. How would you approach this using AI?', 'Use AI to categorize or cluster similar complaints and identify common themes.', 'AI can make piles of similar complaints so you quickly see the biggest problems.'),
  ('medium', 'Your manager wants a chatbot that can answer employee questions using company HR policies. What information should the chatbot use as its knowledge source?', 'Connect it to approved company HR policies and documents.', 'The chatbot should answer from the company''s real rulebook, not make up rules.'),
  ('medium', 'AI summarizes a financial report but mentions a number you cannot find. What should you do next?', 'Don''t use it until you verify it against the original report.', 'AI is a smart helper, but it can still make mistakes.'),
  ('medium', 'Your sales team spends hours manually updating CRM records after calls. Where could AI or automation fit?', 'Use AI to summarize calls and automation to update relevant CRM fields.', 'AI understands what happened, then automation puts useful details into the correct boxes.'),
  ('medium', 'A client says, “We want AI because our competitors are using it.” What should you understand first?', 'Identify the actual business problem.', 'Buying AI without a problem is like buying a hammer before checking whether you have a nail.'),
  ('medium', 'Your team receives hundreds of support emails daily. How could AI help prioritize them?', 'Use AI to classify and prioritize emails, while humans handle important cases.', 'AI can sort emails into urgent, normal and low priority.'),
  ('medium', 'Your client wants to predict which customers may stop using its service. What historical data would you need?', 'Historical customer behavior and churn data.', 'Show AI examples of customers who stayed and left so it can look for patterns.'),
  ('medium', 'You have five years of sales data and need to estimate next quarter. What type of analytics problem is this?', 'Forecasting or predictive analytics.', 'Use what happened before to make an educated guess about what may happen next.'),
  ('medium', 'A recruitment team receives 2,000 résumés for 20 positions. How could AI assist safely?', 'AI can organize relevant résumés, but humans should make important hiring decisions.', 'AI can make a smaller pile, but a person should still decide who gets the job.'),
  ('medium', 'You want an AI assistant to answer specifically from your organization''s documents. What setup would you recommend?', 'Use a company knowledge base with RAG.', 'AI searches your company''s documents and uses them to answer your question.'),
  ('medium', 'A client wants to automate invoice processing. Which parts could be automated?', 'Read invoices, extract fields, validate information and enter approved data into the ERP.', 'AI can read vendor, amount and date instead of a person typing every value.'),
  ('medium', 'Customer service wants AI to respond to every complaint automatically. What risk should you consider?', 'Use human review for sensitive or high-risk complaints.', 'Simple questions may be fine for AI, but serious cases may need a person.'),
  ('medium', 'Your AI meeting summary misses important decisions. How would you improve it?', 'Improve the instructions and give AI a full, clear transcript.', 'Ask specifically for decisions, action items, owners and deadlines.'),
  ('medium', 'Your team wants to upload confidential client documents to a public AI tool. What should you check first?', 'Check company privacy and security policies.', 'Make sure the AI tool is approved and safe before sharing private information.'),
  ('medium', 'Marketing wants personalized emails for 100,000 customers. How could AI help?', 'Use customer segments, AI-generated templates and automation.', 'AI can make different messages for different groups instead of writing each one by hand.'),
  ('medium', 'A client asks whether they need AI when an Excel formula could solve the problem. How would you decide?', 'Use the simplest technology that solves the problem.', 'If Excel is enough, you don''t need a robot.'),
  ('medium', 'A manager says, “Build me a dashboard,” with no other details. What should you ask?', 'Ask what decisions it should help make and which metrics matter.', 'Before drawing a map, you need to know where the person wants to go.'),
  ('medium', '25% of sales rows are missing customer locations. What should you do before location analysis?', 'Investigate and clean missing data before strong conclusions.', 'If many people did not answer, you shouldn''t pretend you know their answers.'),
  ('medium', 'Your client wants to know why sales dropped. Why isn''t asking a chatbot enough?', 'Analyze actual business data and possible causes.', 'AI does not magically know what happened inside the company; you need evidence.'),
  ('medium', 'An AI system categorizes emails incorrectly. What would you investigate?', 'Review wrong examples, category definitions, prompts or training data, and performance.', 'Look at where AI got confused and improve its rules or examples.'),
  ('medium', 'Your team spends two hours every morning collecting data from five systems. How would you assess automation?', 'Map the process and compare automation cost with time and value saved.', 'Understand the repeated steps, then see if a computer can do them safely and cheaply.'),
  ('medium', 'Customer feedback contains names and phone numbers. What should happen before using AI?', 'Remove or mask personal information and use an approved secure AI system.', 'AI does not need someone''s phone number just to understand their feedback.'),
  ('medium', 'An executive asks for an “AI dashboard.” How would you clarify the need?', 'Clarify the business goal instead of assuming AI is required.', 'Ask what they are trying to understand or decide.'),
  ('medium', 'Your organization wants employees to use generative AI safely. What controls could help?', 'Use approved tools, access controls, data policies and employee training.', 'Give people clear rules about what they can and cannot share with AI.'),
  ('medium', 'Your client wants AI to identify fraudulent transactions. What data would help?', 'Historical transactions, especially known fraud and legitimate transactions.', 'Show AI examples of normal and bad transactions so it learns suspicious patterns.'),
  ('medium', 'A sales manager wants to score leads by likelihood of buying. What inputs could be used?', 'Signals such as activity, past purchases, company details and engagement.', 'Someone who visits the pricing page often may be more interested.'),
  ('medium', 'An AI assistant gives different answers to similar questions. Why, and how can you reduce it?', 'LLM outputs can vary; use clearer prompts, controlled settings and trusted sources.', 'Small changes in a question can change AI''s answer, so give it clearer rules.'),
  ('medium', 'You need AI to extract fields from thousands of invoices with different layouts. What capability would you use?', 'Intelligent document processing or OCR plus AI extraction.', 'AI can find important information even when it appears in different places.'),
  ('medium', 'Your company wants every customer call summarized and saved to CRM. What workflow makes sense?', 'Transcribe, summarize, extract key information, check when needed, then update CRM.', 'Think: call → words → useful points → check → CRM.'),
  ('medium', 'An AI-generated client report has no sources. What should you do before sharing?', 'Verify important claims against reliable sources.', 'If AI gives a number, you should be able to show where it came from.'),
  ('hard', 'A bank wants AI to automatically reject suspicious transactions, but false positives could block legitimate customers. How would you design the decision process?', 'Use risk scores and thresholds, with human review for uncertain or high-impact cases.', 'Use levels: low risk can pass, uncertain cases go to a person, and very high risk gets stopped or reviewed.'),
  ('hard', 'A client wants to replace 50% of customer-service agents with AI because costs are high. How would you evaluate it?', 'Study the work first and identify tasks AI can safely automate or assist.', 'Don''t start with removing people. Find which work takes time and whether AI can help.'),
  ('hard', 'An attrition model is 90% accurate but performs poorly for one employee group. Would you deploy it?', 'Don''t deploy it blindly. Investigate bias and performance across groups first.', '90% sounds good, but it is a problem if most mistakes happen to the same group.'),
  ('hard', 'An internal AI assistant searches confidential documents with different permissions. How do you prevent unauthorized access?', 'Keep document permissions and access controls in the AI system.', 'If someone cannot normally open a secret file, AI should not show it either.'),
  ('hard', 'A client wants AI to decide who receives loans. What risks and controls matter?', 'Check fairness, explainability, privacy, regulation, data quality and human oversight.', 'Loans affect people''s lives, so AI should not make unfair or mysterious decisions.'),
  ('hard', 'Your AI support bot confidently gives incorrect refund information. How would you reduce this?', 'Ground it in approved policies, test it, and send uncertain cases to humans.', 'Make the bot use the real rulebook, and ask a person when it is unsure.'),
  ('hard', 'Customer data is spread across CRM, Excel, emails and ERP. Leadership wants AI insights. What first?', 'Integrate, clean and govern the data first.', 'AI cannot cook a good meal with messy ingredients stored in different kitchens.'),
  ('hard', 'An executive wants “our own ChatGPT trained on all company information.” How do you turn this into requirements?', 'Define use cases, users, data, permissions and success metrics.', 'Ask who uses it, what they ask, what it can see, what it does and how success is measured.'),
  ('hard', 'A fraud model flags 20% of transactions, but investigators can review only 2%. How would you redesign it?', 'Prioritize alerts using risk levels and available investigation capacity.', 'If AI shouts danger too often, rank the most dangerous cases first.'),
  ('hard', 'A consulting team wants AI to use previous projects for recommendations. How do you protect client confidentiality?', 'Separate client data and enforce strict access and privacy controls.', 'Client A''s secrets should never appear in Client B''s work.'),
  ('hard', 'An AI model is technically excellent but employees refuse to use it. What would you investigate?', 'Usability, trust, workflow fit, training and incentives.', 'A great bicycle does not help if nobody knows how, when or why to ride it.'),
  ('hard', 'Churn predictions are accurate but the business doesn''t know what action to take. Is the model delivering value?', 'Not fully. The business needs actions tied to the prediction.', 'Knowing a customer may leave is not enough; you need a plan to help them stay.'),
  ('hard', 'Historical hiring data may contain bias. How should an AI screening system be approached?', 'Test historical data for bias and keep appropriate human oversight.', 'If people made unfair choices before, AI can learn those unfair patterns too.'),
  ('hard', 'A client asks whether to build an AI solution or buy a product. What factors matter?', 'Cost, customization, speed, security, maintenance, skills and strategic importance.', 'It is like deciding whether to cook or order food; it depends on your needs and resources.'),
  ('hard', 'A recommendation system is accurate but needs lots of personal data. How do you balance privacy?', 'Collect only necessary data, get proper consent and protect it.', 'Use only the personal information you truly need, not everything you can collect.'),
  ('hard', 'Automated invoice approvals later allow fraud. What may have gone wrong?', 'The system may have lacked validation, fraud controls, monitoring or human checkpoints.', 'If a robot checks only a few boxes, bad actors may learn how to make those boxes match.'),
  ('hard', 'How should leadership measure whether a generative-AI assistant is successful beyond number of users?', 'Measure task completion, accuracy, time saved, quality, adoption and user satisfaction.', 'Opening the tool is not success. Finishing work better or faster is.'),
  ('hard', 'A bank fraud model worked for two years but accuracy falls. What might have changed?', 'Real-world patterns may have changed; investigate model or data drift.', 'The world changes, so old patterns may stop working and the AI may need updating.'),
  ('hard', 'An LLM summarizes legal contracts but sometimes misses unusual clauses. What is a safer workflow?', 'Let AI assist, but require human review for important clauses and decisions.', 'AI can be the first reader, but a qualified person should be the final checker.'),
  ('hard', 'A chatbot needs information from 15 systems that change often. What should happen before launch?', 'Build reliable integrations and a trusted information layer.', 'The chatbot needs a safe bridge to the newest information or it may give old answers.'),
  ('hard', 'Your AI system is 95% accurate. Is that good enough to launch?', 'It depends on the consequences and types of the remaining errors.', '95% may be great for movies but dangerous for life-or-death decisions.'),
  ('hard', 'A hospital wants AI to prioritize patient requests. Why is this different from support tickets?', 'Medical decisions need stronger safety, privacy, validation and human oversight.', 'A wrong support answer is annoying; a wrong medical priority could hurt someone.'),
  ('hard', 'An insurer wants AI to write claim decisions and send them automatically. Where should humans review?', 'High-impact, uncertain, disputed or unusual decisions.', 'AI can prepare the work, but a person should check important decisions.'),
  ('hard', 'You have 100 AI use cases but budget for five. How should you prioritize?', 'Business value, feasibility, risk, data readiness and effort or cost.', 'Ask if it helps, can be built, has data, is safe and is worth the cost.'),
  ('hard', 'A client spends ₹10 crore on AI that saves only 10 minutes per month. What went wrong?', 'The investment was not tied to a valuable problem and measurable ROI.', 'It is like buying a helicopter to cross the street.'),
  ('hard', 'Employees copy AI analysis into client presentations without checking it. How would you redesign the process?', 'Add sources, review steps, approval rules and accountability into the workflow.', 'Don''t only say be careful; make checking a required part of the process.'),
  ('hard', 'An AI assistant is 98% correct but the 2% errors could cause regulatory trouble. What should change?', 'Add stronger controls, human review and restricted automation for high-risk outputs.', 'An elevator that works 98% of the time would not feel safe. Risk changes what good enough means.'),
  ('hard', 'An AI agent can read emails, update CRM, schedule meetings and send responses. What safeguards are needed?', 'Minimum permissions, approval checkpoints, logs, action limits and an emergency stop.', 'Give AI only the keys it truly needs, not the keys to the whole building.'),
  ('hard', 'Different departments deploy many AI tools and costs/security risks rise. What governance is needed?', 'Centralized AI governance with approved tools, standards, ownership, monitoring and shared policies.', 'The company needs common AI rules instead of every team making its own.'),
  ('hard', 'A CEO wants AI to make the organization 30% more productive. How do you turn this into solvable problems?', 'Break the goal into workflows, find bottlenecks, identify AI opportunities and define measurable outcomes.', 'Find where people lose time, test whether AI reduces it, and measure the result.');
