-- General knowledge quiz (Tech_AI_MCQ_Quiz_120Q.xlsx) and fixed-answer scenario
-- quiz (Vantage_90_Scenario_Questions.xlsx) — two content banks supplied directly
-- by the user rather than generated by lib/jargon-pipeline or lib/content-pipeline.
--
-- Neither reuses an existing table:
--  - The MCQ bank has no single-word "term" per question (full Q&A, not
--    definition-to-term), so it doesn't fit daily_quiz_questions' term-based
--    grading (recordJargonAttempt checks against `term`, not `correct_answer`).
--  - The scenario bank ships a fixed `answer` per scenario, which practice_cases
--    deliberately never stores — recommendCategory() judges live against the
--    taxonomy so practice can't drift from it (see 0004_seed_practice_cases.sql).
-- Both are separate, static question types with no live-generation pipeline.

create table if not exists general_quiz_questions (
  id uuid primary key default gen_random_uuid(),
  difficulty text not null check (difficulty in ('easy', 'medium', 'hard')),
  question_text text not null,
  options jsonb not null,
  correct_answer text not null,
  explanation text not null,
  flagged boolean not null default false,
  created_at timestamptz not null default now(),
  check (jsonb_typeof(options) = 'array')
);

create table if not exists general_quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  question_id uuid not null references general_quiz_questions(id) on delete cascade,
  selected_answer text not null,
  correct boolean not null,
  seconds numeric,
  created_at timestamptz not null default now()
);

create table if not exists scenario_quiz_questions (
  id uuid primary key default gen_random_uuid(),
  difficulty text not null check (difficulty in ('easy', 'medium', 'hard')),
  question_text text not null,
  answer text not null,
  explanation text not null,
  flagged boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists scenario_quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  question_id uuid not null references scenario_quiz_questions(id) on delete cascade,
  seconds numeric,
  created_at timestamptz not null default now()
);

alter table general_quiz_questions enable row level security;
create policy "read unflagged general quiz questions" on general_quiz_questions
  for select to authenticated using (flagged = false);
alter table general_quiz_attempts enable row level security;
create policy "own general quiz attempts" on general_quiz_attempts for all using (auth.uid() = user_id);

alter table scenario_quiz_questions enable row level security;
create policy "read unflagged scenario quiz questions" on scenario_quiz_questions
  for select to authenticated using (flagged = false);
alter table scenario_quiz_attempts enable row level security;
create policy "own scenario quiz attempts" on scenario_quiz_attempts for all using (auth.uid() = user_id);

